export const getGetInternalChatUrl = (section: 'declutter' | 'organize_thoughts',
    params?: GetInternalChatParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/internal-chat/${section}?${stringifiedParams}` : `/api/internal-chat/${section}`
}

